def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([0]), fmt([1, 2, 3, 4, 5]), fmt([0, 0]), fmt([10**9, 10**9, 10**9]), fmt([7, 0, 7]), fmt([1, 1, 1, 1])]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for hi in (3, 10, 10**9):
            tests.append(fmt([rng.randint(0, hi) for _ in range(n)]))
    n = 100000
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(n)]))
    a = [rng.randint(1, 10**9) for _ in range(n)]
    a[n // 2] = 0
    tests.append(fmt(a))
    tests.append(fmt([10**9] * n))
    tests.append(fmt([1] * n))
    return tests
